    line-height: 4rem;
    width: 4rem
}

.icon-xxxl {
    height: 7rem;
    line-height: 7rem;
    width: 7rem
}

.icon-shape {
    align-items: center;
    display: inline-flex;
    justify-content: center;
    text-align: center;
    vertical-align: middle
}

.border-dashed {
    border: 1px dashed var(--fc-gray-300) !important
}

.img-zoom {
    border-radius: .5rem;
    overflow: hidden
}

.img-zoom img {
    transition: transform .5s ease
}

.img-zoom img:hover {
    transform: scale(1.1)
}

div.zoom {
    background-position: 50% 50%;
    border-radius: .5rem;
    cursor: zoom-in;
    overflow: hidden;
    position: relative;
    width: 100%
}

div.zoom img:hover {
    opacity: 0
}

div.zoom img {
    display: block;
    transition: opacity .5s;
    width: 100%
}

.simplebar-scrollbar:before {
    background: var(--fc-gray-400)
}

