    animation-direction: var(--z, normal);
    animation-duration: var(--1b, 1s);
    animation-iteration-count: var(--1c, infinite);
    animation-name: fa-spin;
    animation-timing-function: var(--1d, steps(8))
}

@keyframes fa-beat {

    0%,
    90% {
        transform: scale(1)
    }

    45% {
        transform: scale(var(--1e, 1.25))
    }
}

@keyframes fa-bounce {
    0% {
        transform: scale(1) translateY(0)
    }

    10% {
        transform: scale(var(--1f, 1.1), var(--1g, .9)) translateY(0)
    }

    30% {
        transform: scale(var(--1h, .9), var(--1i, 1.1)) translateY(var(--1j, -.5em))
    }

    50% {
        transform: scale(var(--1k, 1.05), var(--1l, .95)) translateY(0)
    }

    57% {
        transform: scale(1) translateY(var(--1m, -.125em))
    }

    64% {
        transform: scale(1) translateY(0)
    }

    to {
        transform: scale(1) translateY(0)
    }
}

@keyframes fa-fade {
    50% {
        opacity: var(--1n, .4)
    }
}

@keyframes fa-beat-fade {

    0%,
    to {
        opacity: var(--1o, .4);
        transform: scale(1)
    }

    50% {
        opacity: 1;
        transform: scale(var(--1p, 1.125))
    }
}

@keyframes fa-flip {
    50% {
        transform: rotate3d(var(--1q, 0), var(--1r, 1), var(--1s, 0), var(--1t, -180deg))
    }
}

@keyframes fa-shake {
    0% {
        transform: rotate(-15deg)
    }

    4% {
        transform: rotate(15deg)
    }

    24%,
    8% {
        transform: rotate(-18deg)
    }

    12%,
    28% {
        transform: rotate(18deg)
    }

    16% {
        transform: rotate(-22deg)
    }

    20% {
        transform: rotate(22deg)
    }

    32% {
        transform: rotate(-12deg)
    }

    36% {
        transform: rotate(12deg)
    }

    40%,
    to {
        transform: rotate(0deg)
    }
}

@keyframes fa-spin {
    0% {
        transform: rotate(0deg)
    }

    to {
        transform: rotate(1turn)
    }
}

.fa-rotate-90 {
    transform: rotate(90deg)
}

.fa-rotate-180 {
    transform: rotate(180deg)
}

.fa-rotate-270 {
    transform: rotate(270deg)
}

.fa-flip-horizontal {
    transform: scaleX(-1)
}

.fa-flip-vertical {
    transform: scaleY(-1)
}

.fa-flip-both,
.fa-flip-horizontal.fa-flip-vertical {
    transform: scale(-1)
}

.fa-rotate-by {
    transform: rotate(var(--10, none))
}

.fa-stack {
    display: inline-block;
    height: 2em;
    line-height: 2em;
    position: relative;
    vertical-align: middle;
    width: 2.5em
}

.fa-stack-1x,
.fa-stack-2x {
    left: 0;
    position: absolute;
    text-align: center;
    width: 100%;
    z-index: var(--11, auto)
}

.fa-stack-1x {
    line-height: inherit
}

.fa-stack-2x {
    font-size: 2em
}

