.nice-select {
    -webkit-tap-highlight-color: transparent;
    background-color: #fff;
    border: 1px solid #e8e8e8;
    border-radius: 5px;
    box-sizing: border-box;
    clear: both;
    cursor: pointer;
    display: block;
    float: left;
    font-family: inherit;
    font-weight: 400;
    height: 42px;
    line-height: 2.5rem;
    outline: none;
    padding-left: 18px;
    padding-right: 30px;
    position: relative;
    text-align: left !important;
    transition: all .2s ease-in-out;
    -webkit-user-select: none;
    -moz-user-select: none;
    user-select: none;
    white-space: nowrap;
    width: auto
}

.nice-select:hover {
    border-color: #dbdbdb
}

.nice-select.open,
.nice-select:active,
.nice-select:focus {
    border-color: #999
}

.nice-select:after {
    border-bottom: 2px solid #999;
    border-right: 2px solid #999;
    content: "";
    display: block;
    height: 5px;
    margin-top: -4px;
    pointer-events: none;
    position: absolute;
    right: 12px;
    top: 50%;
    transform: rotate(45deg);
    transform-origin: 66% 66%;
    transition: all .15s ease-in-out;
    width: 5px
}

.nice-select.open:after {
    transform: rotate(-135deg)
}

.nice-select.open .list {
    opacity: 1;
    pointer-events: auto;
    transform: scale(1) translateY(0)
}

.nice-select.disabled {
    border-color: #ededed;
    color: #999;
    pointer-events: none
}

.nice-select.disabled:after {
    border-color: #ccc
}

.nice-select.wide {
    width: 100%
}

.nice-select.wide .list {
    left: 0 !important;
    right: 0 !important
}

.nice-select.right {
    float: right
}

.nice-select.right .list {
    left: auto;
    right: 0
}

.nice-select.small {
    font-size: .75rem;
    height: 36px;
    line-height: 2.125rem
}

.nice-select.small:after {
    height: 4px;
    width: 4px
}

.nice-select.small .option {
    line-height: 2.125rem;
    min-height: 34px
}

.nice-select .list {
    background-color: #fff;
    box-sizing: border-box;
    left: 0;
    margin-top: 4px;
    opacity: 0;
    overflow: hidden;
    padding: 0;
    pointer-events: none;
    position: absolute;
    transform: scale(.75) translateY(-21px);
    transform-origin: 50% 0;
    transition: all .2s cubic-bezier(.5, 0, 0, 1.25), opacity .15s ease-out;
    z-index: 9
}

.nice-select .list:hover .option:not(:hover) {
    background-color: transparent !important
}

.nice-select .option {
    cursor: pointer;
    font-weight: 400;
    line-height: 2.5rem;
    list-style: none;
    min-height: 40px;
    outline: none;
    padding-left: 18px;
    padding-right: 29px;
    text-align: left;
    transition: all .2s
}

.nice-select .option.focus,
.nice-select .option.selected.focus,
.nice-select .option:hover {
    background-color: #f6f6f6
}

.nice-select .option.selected {
    font-weight: 700
}

.nice-select .option.disabled {
    background-color: transparent;
    color: #999;
    cursor: default
}

.no-csspointerevents .nice-select .list {
    display: none
}

.no-csspointerevents .nice-select.open .list {
    display: block
}

.nice-select .list::-webkit-scrollbar {
    width: 0
}

.nice-select .list {
    border-radius: 5px;
    max-height: 210px;
    overflow-y: scroll;
    top: 100%
}

.nice-select .nice-select-search-box+.list {
    padding: 52px 0 0
}

.nice-select .nice-select-search-box+.list .disabled {
    display: none !important
}

.nice-select.has-multiple {
    height: auto;
    line-height: 1.375rem;
    min-height: 53px;
    padding: 7px 12px;
    white-space: inherit
}

.nice-select.has-multiple span.current {
    background: #eee;
    border: 1px solid #ccc;
    border-radius: 3px;
    display: inline-block;
    font-size: .875rem;
    line-height: 1.5rem;
    margin-bottom: 3px;
    margin-right: 3px;
    padding: 0 10px
}

.nice-select.has-multiple .multiple-options {
    display: block;
    line-height: 2.3125rem;
    margin-left: 30px;
    padding: 0
}

.nice-select .nice-select-search-box {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 5px 5px 0 0;
    box-sizing: border-box;
    left: 0;
    margin-top: 5px;
    opacity: 0;
    padding: 5px;
    pointer-events: none;
    position: absolute;
    top: 100%;
    transform: scale(.75) translateY(-21px);
    transform-origin: 50% 0;
    transition: all .2s cubic-bezier(.5, 0, 0, 1.25), opacity .15s ease-out;
    width: 100%;
    z-index: 8
}

.nice-select .nice-select-search {
    background-color: #fff;
    border: 1px solid #ddd;
    border-radius: 3px;
    box-sizing: border-box;
    color: #333;
    display: inline-block;
    height: auto;
    line-height: 1.375rem;
    margin: 0 10px 0 0;
    min-height: 36px;
    outline: 0 !important;
    padding: 7px 12px;
    vertical-align: middle;
    width: 100% !important
}

.nice-select.open .nice-select-search-box {
    opacity: 1;
    pointer-events: auto;
    transform: scale(1) translateY(0);
    z-index: 10
}

