details.readmore {
    cursor: text;
    position: relative;
    text-align: left
}

details.readmore summary {
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    display: -webkit-box;
    overflow: hidden;
    pointer-events: none
}

details.readmore summary:after {
    color: #1f1f27;
    cursor: pointer;
    display: block;
    margin-top: -1rem;
    pointer-events: auto;
    position: absolute;
    text-decoration: underline;
    top: 100%
}

details.readmore:not([open]) {
    padding-bottom: 1rem
}

details.readmore:not([open]) summary:after {
    content: attr(data-more)
}

details.readmore[open] summary {
    -webkit-line-clamp: unset
}

details.readmore[open] summary :after {
    content: attr(data-less);
    top: 100%
}

details.accordion summary {
    cursor: pointer
}

details.accordion summary::marker {
    content: ""
}

details.accordion summary:before {
    content: "\f107";
    font-family: Font Awesome\ 6 Free, sans-serif;
    font-style: normal;
    font-weight: 900;
    margin-left: -1.25rem;
    margin-top: 3px;
    position: absolute;
    transition: transform .3s ease
}

details.accordion[open] summary:before {
    transform: rotate(180deg)
}



