.switch input[type=checkbox] {
    background: grey;
    border-radius: 22px;
    cursor: pointer;
    display: block;
    height: 22px;
    position: relative;
    transition: background .3s;
    width: 44px
}

.switch input[type=checkbox]:active:after {
    width: 29.3333333333px
}

.switch input[type=checkbox]:after {
    background: #fff;
    border-radius: 19.8px;
    content: "";
    height: 19.8px;
    left: 1.1px;
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    transition: all .3s, transform .3s, left .3s;
    width: 19.8px
}

.switch input[type=checkbox]:checked {
    background: #fdd835
}

.switch input[type=checkbox]:checked:after {
    left: calc(100% - 1.1px);
    transform: translate(-100%, -50%)
}

.switch label {
    cursor: pointer
}

.switch.disabled {
    pointer-events: none
}

.switch.disabled input {
    opacity: .75
}

